import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CC9cRD7J.js";const f=JSON.parse('{"title":"Registro de Actualizaciones","description":"Historial de versiones y changelog automático de StaffPlus","frontmatter":{"title":"Registro de Actualizaciones","description":"Historial de versiones y changelog automático de StaffPlus"},"headers":[],"relativePath":"actualizaciones/index.md","filePath":"actualizaciones/index.md","lastUpdated":1793577989000}'),o={name:"actualizaciones/index.md"};function s(n,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="🚀-registro-de-actualizaciones-changelog" tabindex="-1">🚀 Registro de Actualizaciones (Changelog) <a class="header-anchor" href="#🚀-registro-de-actualizaciones-changelog" aria-label="Permalink to &quot;🚀 Registro de Actualizaciones (Changelog)&quot;">​</a></h1><blockquote><p>🔄 <strong>Página Automatizada:</strong> Esta sección se sincroniza y compila automáticamente cada vez que se publica una nueva actualización en <a href="https://modrinth.com/plugin/staff-plus" target="_blank" rel="noreferrer">Modrinth</a> o en GitHub.</p></blockquote><hr><h2 id="staffplus-5-0-4-ultima-version" tabindex="-1">Staffplus 5.0.4 <span class="custom-badge required">Última Versión</span> <a class="header-anchor" href="#staffplus-5-0-4-ultima-version" aria-label="Permalink to &quot;Staffplus 5.0.4 &lt;span class=&quot;custom-badge required&quot;&gt;Última Versión&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 31 de octubre de 2026</li><li>🎮 <strong>Minecraft:</strong> <code>1.17 — 26.3</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>purpur</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/rp1ewjRX/staff-5.0.4.jar" target="_blank" rel="noreferrer"><code>staff-5.0.4.jar</code></a> (1.34 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/5.0.4" target="_blank" rel="noreferrer">Ver versión 5.0.4</a></li></ul><h3 id="📋-notas-de-la-version" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><p>📦 StaffPlus v5.0.4 — Release Notes 🚀 Compatibility &amp; Performance</p><ul><li>Improved automatic Bukkit, Paper 26.x, and Minecraft 1.21.x version detection.</li><li>Added support for protocols v26_1_R1, v26_2_R1, v26_3_R1, and v1_21_R1.</li><li>Reduced compatibility issues and NMS-related errors.</li><li>Improved configuration and data file handling.</li></ul><p>🛡️ Advanced Punishment System</p><ul><li>Added /ban, /tempban, /banip, /tempbanip, /unban, /unbanip, and /baninfo commands.</li><li>Added player IP history tracking.</li><li>Introduced a graphical punishment interface with /bangui.</li><li>Integrated punishment actions directly into /examine.</li><li>Added redesigned kick and ban screens with detailed punishment information.</li></ul><p>🔒 Staff Mode Protection</p><ul><li>Prevents staff mode items from being moved, removed, or replaced.</li><li>Added protection against creative inventory manipulation.</li><li>Blocks item dropping (Q) and offhand swapping (F).</li><li>Prevents accidental interactions with entities and armor stands.</li><li>Disabled ground item pickup while in Staff Mode.</li></ul><p>🐛 Critical Bug Fixes</p><ul><li>Fixed the Ender Eye issue when using RTP.</li><li>Improved protocol adapter stability.</li><li>Unified all 14 modules into a single distributable JAR.</li><li>Bundled required dependencies for easier installation.</li></ul><p>📌 Summary: StaffPlus 5.0.4 brings improved compatibility with newer Minecraft versions, a complete ban and IP punishment system, stronger Staff Mode protection, and important stability fixes.</p><hr><h2 id="staffplus-5-0-1-version-anterior" tabindex="-1">Staffplus 5.0.1 <span class="custom-badge optional">Versión Anterior</span> <a class="header-anchor" href="#staffplus-5-0-1-version-anterior" aria-label="Permalink to &quot;Staffplus 5.0.1 &lt;span class=&quot;custom-badge optional&quot;&gt;Versión Anterior&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 28 de julio de 2026</li><li>🎮 <strong>Minecraft:</strong> <code>1.17 — 26.2</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/dVOozxaJ/staff-5.00.jar" target="_blank" rel="noreferrer"><code>staff-5.00.jar</code></a> (1.25 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/5.0.0" target="_blank" rel="noreferrer">Ver versión 5.0.0</a></li></ul><h3 id="📋-notas-de-la-version-1" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version-1" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><h1 id="🚀-improved-bukkit-version-detection" tabindex="-1">🚀 Improved Bukkit Version Detection <a class="header-anchor" href="#🚀-improved-bukkit-version-detection" aria-label="Permalink to &quot;🚀 Improved Bukkit Version Detection&quot;">​</a></h1><p>Reworked the server version parser to fully support Paper&#39;s modern versioning scheme (e.g. 26.x.x instead of the legacy 1.x.x format). Ensures the correct protocol adapter is selected automatically instead of disabling the plugin on newer server versions.</p><h1 id="🛡️-crash-resistant-protocol-adapters" tabindex="-1">🛡️ Crash-Resistant Protocol Adapters <a class="header-anchor" href="#🛡️-crash-resistant-protocol-adapters" aria-label="Permalink to &quot;🛡️ Crash-Resistant Protocol Adapters&quot;">​</a></h1><p>Refactored the following protocol modules: Protocol_v26_1_R1 Protocol_v26_2_R1 Protocol_v26_3_R1 Protocol_v1_21_R1 Replaced direct dependencies on version-specific (obfuscated) NMS classes with stable Bukkit/Paper APIs: PersistentDataContainer for custom data storage hidePlayer() / showPlayer() for vanish handling Kyori Adventure Components for JSON text and hover events Greatly improves compatibility across future Paper updates and significantly reduces the risk of plugin crashes after minor server updates.</p><hr><h2 id="staff-plus-4-0-0-version-anterior" tabindex="-1">Staff-plus 4.0.0 <span class="custom-badge optional">Versión Anterior</span> <a class="header-anchor" href="#staff-plus-4-0-0-version-anterior" aria-label="Permalink to &quot;Staff-plus 4.0.0 &lt;span class=&quot;custom-badge optional&quot;&gt;Versión Anterior&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 17 de diciembre de 2025</li><li>🎮 <strong>Minecraft:</strong> <code>1.17 — 1.21.11</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/FThgB96b/Staff%2B.jar" target="_blank" rel="noreferrer"><code>Staff+.jar</code></a> (0.90 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/4.0.0" target="_blank" rel="noreferrer">Ver versión 4.0.0</a></li></ul><h3 id="📋-notas-de-la-version-2" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version-2" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><p>✅ 12 idiomas agregados (DE, EN, ES, FR, HR, HU, IT, NL, NO, PT, SV, ZH) ✅ APIs de Bukkit deprecadas actualizadas ✅ Sistema de recogida de items corregido (Cuerda) ✅ Visualización de cofres sin eliminar items ✅ 11 adaptadores de versión reestructurados ✅ Compatible con Minecraft 1.17 - 1.21.11</p><hr>',29)])])}const h=a(o,[["render",s]]);export{f as __pageData,h as default};
